68	 */
69	
70	@RestController
71	@CrossOrigin(exposedHeaders = "errors, content-type")
72	@RequestMapping("/api")
73	public class OwnerRestControllerV1 implements OwnersApi {
74	
75	    /**
76	     * Syntactic check for an email address: a non-empty local part, a single {@code @}, and a
77	     * domain containing at least one dot, with no whitespace in any part.
78	     */
79	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
80	
81	    /**
82	     * Email domains belonging to disposable/throwaway mail providers. An owner whose email domain
83	     * (the part after the {@code @}, compared case-insensitively) is listed here is rejected: such
84	     * addresses are not durable contact details. Entries are stored lower-cased.
85	     */
86	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
87	        "mailinator.com",
88	        "tempmail.com",
89	        "guerrillamail.com");
90	
91	    /**
92	     * Dedicated audit logger. On a successful owner create an audit line is emitted here carrying the
93	     * new owner's id, customer code and registration date.
94	     */
95	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
96	
97	    /**
98	     * Common street-type abbreviations expanded during address normalization. Keys are the
99	     * upper-cased abbreviation as it appears as a whole whitespace-delimited token; values are the
100	     * expanded form it is replaced with.
101	     */
102	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
103	        "ST", "STREET",
104	        "RD", "ROAD",
105	        "AVE", "AVENUE");
106	
107	    /**
108	     * The maximum number of owners a single city may contain. Once a city holds this many owners it
109	     * is at capacity and cannot take any more.
110	     */
111	    private static final int CITY_CAPACITY = 50;
112	
113	    /**
114	     * The maximum number of owners that may be registered in a single day. Once this many owners
115	     * already carry today's {@code registrationDate}, the day's quota is exhausted and no further
116	     * owners can be created that day.
117	     */
118	    private static final int DAILY_OWNER_LIMIT = 100;
119	
120	    /**
121	     * The number of owners that may be registered on a single business day before a response starts
122	     * carrying a {@code bulkSignupWarning}. Once <em>more than</em> this many owners already carry the
123	     * current business day's {@code registrationDate}, that day's signups are flagged as unusually
124	     * high volume.
125	     */
126	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
127	
128	    /**
129	     * E.164 country codes mapped to the exact number of national (significant) digits a telephone for
130	     * that country must carry. For example {@code '+61'} (Australia) requires 9 national digits and
131	     * {@code '+1'} (NANP) requires 10. A country code listed here enforces that national-number length;
132	     * a number whose country code is not listed is accepted at any otherwise-valid E.164 length.
133	     */
134	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
135	        "61", 9,
136	        "1", 10);
137	
138	    /**
139	     * Fixed region-to-postcode-range lookup used both to validate an owner's optional postcode against
140	     * the region derived from the owner's city ({@link #regionForCity}) and to derive the postcode's own
141	     * region for the {@code customerCode} ({@link #regionForPostcode}). Each value is the inclusive
142	     * {@code {low, high}} 4-digit range for that region (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A
143	     * region that is not listed ({@code 'UNKNOWN'}) carries no range and accepts any 4-digit postcode.
144	     */
145	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
146	        "NSW", new int[] {2000, 2099},
147	        "VIC", new int[] {3000, 3099},
148	        "QLD", new int[] {4000, 4099});
149	
150	    /**
151	     * Fixed city-to-region lookup used to validate an owner's optional postcode against the region
152	     * derived from the owner's city. Any city not listed has region {@code 'UNKNOWN'} and so accepts
153	     * any 4-digit postcode.
154	     */
155	    private static final Map<String, String> CITY_REGION = Map.of(
156	        "Sydney", "NSW",
157	        "Melbourne", "VIC",
158	        "Brisbane", "QLD");
159	
160	    private final ClinicService clinicService;
161	
162	    private final OwnerMapper ownerMapper;
163	
164	    private final PetMapper petMapper;
165	
166	    private final VisitMapper visitMapper;
167	
168	    public OwnerRestControllerV1(ClinicService clinicService,
169	                                 OwnerMapper ownerMapper,
170	                                 PetMapper petMapper,
171	                                 VisitMapper visitMapper) {
172	        this.clinicService = clinicService;
173	        this.ownerMapper = ownerMapper;
174	        this.petMapper = petMapper;
175	        this.visitMapper = visitMapper;
176	    }
177	
178	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
179	    @Override
180	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
181	        Collection<Owner> owners;
182	        if (lastName != null) {
183	            owners = this.clinicService.findOwnerByLastName(lastName);
184	        } else {
185	            owners = this.clinicService.findAllOwners();
186	        }
187	        if (owners.isEmpty()) {
188	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
189	        }
190	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
191	    }
192	
193	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
194	    @Override
195	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
196	        Owner owner = this.clinicService.findOwnerById(ownerId);
197	        if (owner == null) {
198	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
199	        }
200	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
201	        applyBulkSignupWarning(ownerDto);
202	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
203	    }
204	
205	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
206	    @Override
207	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
208	        validateRequiredFields(ownerFieldsDto);
209	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
210	        LocalDate registrationDate = toBusinessDay(
211	            ownerFieldsDto.getRegistrationDate() != null ? ownerFieldsDto.getRegistrationDate() : LocalDate.now());
212	        rejectDailyLimitReached(registrationDate);
213	        HttpHeaders headers = new HttpHeaders();
214	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
215	        String address = normalizeAddress(ownerFieldsDto.getAddress());
216	        owner.setAddress(address);
217	        rejectCityAtCapacity(owner.getCity());
218	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
219	        owner.setTelephone(telephone);
220	        String email = normalizeEmail(ownerFieldsDto.getEmail());
221	        owner.setEmail(email);
222	        owner.setPostcode(validatePostcode(ownerFieldsDto.getPostcode(), regionForCity(owner.getCity())));
223	        owner.setHouseholdId(computeHouseholdId(owner.getLastName(), owner.getPostcode()));
224	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
225	        rejectDuplicateIdentity(owner);
226	        if (!sharesHousehold) {
227	            rejectHouseholdDuplicate(owner);
228	        }
229	        applyPossibleDuplicate(owner, sharesHousehold);
230	        owner.setRegistrationDate(registrationDate);
231	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
232	        owner.setCustomerCode(generateCustomerCode(owner.getPostcode(), owner.getTelephone(), owner.getLastName()));
233	        this.clinicService.saveOwner(owner);
234	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={}",
235	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
236	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
237	        applyBulkSignupWarning(ownerDto);
238	        headers.setLocation(UriComponentsBuilder.newInstance()
239	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
240	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
241	    }
242	
243	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
244	    @Override
245	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
246	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
247	        if (currentOwner == null) {
248	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
249	        }
250	        currentOwner.setAddress(ownerFieldsDto.getAddress());
251	        currentOwner.setCity(ownerFieldsDto.getCity());
252	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
253	        currentOwner.setLastName(ownerFieldsDto.getLastName());
254	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
255	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
256	        this.clinicService.saveOwner(currentOwner);
257	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
258	    }
259	
260	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
261	    @Transactional
262	    @Override
263	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
264	        Owner owner = this.clinicService.findOwnerById(ownerId);
265	        if (owner == null) {
266	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
267	        }
268	        this.clinicService.deleteOwner(owner);
269	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
270	    }
271	
272	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
273	    @Override
274	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
275	        Owner owner = this.clinicService.findOwnerById(ownerId);
276	        if (owner == null) {
277	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
278	        }
279	        HttpHeaders headers = new HttpHeaders();
280	        Pet pet = petMapper.toPet(petFieldsDto);
281	        owner.setId(ownerId);
282	        pet.setOwner(owner);
283	        pet.getType().setName(null);
284	        this.clinicService.savePet(pet);
285	        PetDto petDto = petMapper.toPetDto(pet);
286	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
287	            .buildAndExpand(pet.getId()).toUri());
288	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
289	    }
290	
291	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
292	    @Override
293	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
294	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
295	        if (currentOwner != null) {
296	            Pet currentPet = this.clinicService.findPetById(petId);
297	            if (currentPet != null) {
298	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
299	                currentPet.setName(petFieldsDto.getName());
300	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
301	                this.clinicService.savePet(currentPet);
302	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
303	            }
304	        }
305	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
306	    }
307	
308	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
309	    @Override
310	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
311	        HttpHeaders headers = new HttpHeaders();
312	        Visit visit = visitMapper.toVisit(visitFieldsDto);
313	        Pet pet = new Pet();
314	        pet.setId(petId);
315	        visit.setPet(pet);
316	        this.clinicService.saveVisit(visit);
317	        VisitDto visitDto = visitMapper.toVisitDto(visit);
318	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
319	            .buildAndExpand(visit.getId()).toUri());
320	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
321	    }
322	
323	
324	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
325	    @Override
326	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
327	        Owner owner = this.clinicService.findOwnerById(ownerId);
328	        if (owner != null) {
329	            Pet pet = owner.getPet(petId);
330	            if (pet != null) {
331	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
332	            }
333	        }
334	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
335	    }
336	
337	    /**
338	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
339	     * already rejects {@code null} values and some formats, but a whitespace-only value can still
340	     * satisfy a {@code @Size(min = 1)} constraint; this guard catches those remaining cases.
341	     *
342	     * @param ownerFieldsDto the submitted owner fields
343	     * @throws InvalidOwnerFieldsException if any required field is missing or blank, carrying the
344	     *                                     name of every offending field
345	     */
346	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
347	        List<String> missingFields = new ArrayList<>();
348	        if (isBlank(ownerFieldsDto.getFirstName())) {
349	            missingFields.add("firstName");
350	        }
351	        if (isBlank(ownerFieldsDto.getLastName())) {
352	            missingFields.add("lastName");
353	        }
354	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
355	            missingFields.add("address");
356	        }
357	        if (isBlank(ownerFieldsDto.getCity())) {
358	            missingFields.add("city");
359	        }
360	        if (isBlank(ownerFieldsDto.getTelephone())) {
361	            missingFields.add("telephone");
362	        }
363	        if (!missingFields.isEmpty()) {
364	            throw new InvalidOwnerFieldsException(missingFields);
365	        }
366	    }
367	
368	    private boolean isBlank(String value) {
369	        return value == null || value.isBlank();
370	    }
371	
372	    /**
373	     * Rejects a supplied {@code registrationDate} that is later than the current server date. A
374	     * {@code null} value means the field was omitted and the registration date will default to the
375	     * server date, so there is nothing to reject. A supplied date on or before today is accepted; the
376	     * raw supplied value is compared against the server date before any business-day adjustment.
377	     *
378	     * @param registrationDate the registration date supplied by the client, or {@code null} if omitted
379	     * @throws InvalidOwnerFieldsException if the supplied date is later than the server date, yielding a
380	     *                                     400 Bad Request response
381	     */
382	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
383	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
384	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
385	        }
386	    }
387	
388	    /**
389	     * Validates an owner's optional postcode. A {@code null} value means the field was omitted and is
390	     * left unset, keeping the create contract backward-compatible. When a value is present it must be
391	     * exactly 4 digits, and when the owner's region (derived from its city, {@link #regionForCity})
392	     * has a known postcode range in {@link #REGION_POSTCODES} the postcode must fall within that
393	     * inclusive range. A region with no known range ({@code 'UNKNOWN'}) accepts any 4-digit postcode.
394	     * The returned value is stored and returned unchanged.
395	     *
396	     * @param postcode the raw postcode value submitted by the client, or {@code null} if omitted
397	     * @param region   the owner's region derived from its city
398	     * @return the postcode to store, or {@code null} if none was supplied
399	     * @throws InvalidOwnerFieldsException if a value is present but not a valid 4-digit postcode, or is
400	     *                                     out of range for the city's region, yielding a 400 response
401	     */
402	    private String validatePostcode(String postcode, String region) {
403	        if (postcode == null) {
404	            return null;
405	        }
406	        if (!postcode.matches("[0-9]{4}")) {
407	            throw new InvalidOwnerFieldsException(List.of("postcode"));
408	        }
409	        int[] range = REGION_POSTCODES.get(region);
410	        if (range != null) {
411	            int value = Integer.parseInt(postcode);
412	            if (value < range[0] || value > range[1]) {
413	                throw new InvalidOwnerFieldsException(List.of("postcode"));
414	            }
415	        }
416	        return postcode;
417	    }
418	
419	    /**
420	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes and brackets
421	     * are stripped. When the value carries a leading {@code '+'} the country code it supplies is kept;
422	     * otherwise the number is treated as a national Australian number, so a single leading {@code '0'}
423	     * is dropped and the {@code '+61'} country code is prepended. The result must be a {@code '+'}
424	     * followed by 8 to 15 digits. This E.164 string is what gets stored and returned.
425	     *
426	     * @param telephone the raw telephone value submitted by the client
427	     * @return the telephone in E.164 form, e.g. {@code +61412345678}
428	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number, yielding a
429	     *                                     400 response
430	     */
431	    private String normalizeTelephone(String telephone) {
432	        String e164 = toE164(telephone);
433	        if (e164 == null) {
434	            throw new InvalidOwnerFieldsException(List.of("telephone"));
435	        }
436	        return e164;
437	    }
438	
439	    /**
440	     * Converts a raw telephone value to E.164 form, or returns {@code null} if it cannot form a valid
441	     * E.164 number. Spaces, dashes and brackets are removed; a leading {@code '+'} keeps the supplied
442	     * country code, while a bare national number has a single leading {@code '0'} dropped and the
443	     * {@code '+61'} country code prepended. A valid result is a {@code '+'} followed by 8 to 15 digits,
444	     * and when the supplied country code is one with a known national-number length
445	     * ({@link #NATIONAL_NUMBER_LENGTHS}, e.g. {@code '+61'} => 9, {@code '+1'} => 10) the national
446	     * number must have exactly that many digits.
447	     *
448	     * @param telephone the raw telephone value, possibly {@code null}
449	     * @return the E.164 string, or {@code null} if the value is not a valid E.164 number
450	     */
451	    private String toE164(String telephone) {
452	        if (telephone == null) {
453	            return null;
454	        }
455	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
456	        boolean hasPlus = cleaned.startsWith("+");
457	        String digits = (hasPlus ? cleaned.substring(1) : cleaned).replaceAll("\\D", "");
458	        String nationalSignificant = hasPlus
459	            ? digits
460	            : "61" + (digits.startsWith("0") ? digits.substring(1) : digits);
461	        if (!nationalSignificant.matches("[0-9]{8,15}")) {
462	            return null;
463	        }
464	        if (!hasValidNationalNumberLength(nationalSignificant)) {
465	            return null;
466	        }
467	        return "+" + nationalSignificant;
468	    }
469	
470	    /**
471	     * Checks the national-number length of an E.164 number (country code plus national significant
472	     * digits, no leading {@code '+'}) against the per-country requirement in
473	     * {@link #NATIONAL_NUMBER_LENGTHS}. The longest listed country code that prefixes the number
474	     * selects the requirement, and the remaining digits must number exactly that many. A number whose
475	     * country code is not listed carries no per-country length requirement and is accepted.
476	     *
477	     * @param nationalSignificant the digits of the E.164 number, country code first, without the
478	     *                            leading {@code '+'}
479	     * @return {@code true} if the national-number length is correct for the country code, or the
480	     *         country code has no listed requirement; {@code false} otherwise
481	     */
482	    private boolean hasValidNationalNumberLength(String nationalSignificant) {
483	        String countryCode = NATIONAL_NUMBER_LENGTHS.keySet().stream()
484	            .filter(nationalSignificant::startsWith)
485	            .max(Comparator.comparingInt(String::length))
486	            .orElse(null);
487	        if (countryCode == null) {
488	            return true;
489	        }
490	        int nationalLength = nationalSignificant.length() - countryCode.length();
491	        return nationalLength == NATIONAL_NUMBER_LENGTHS.get(countryCode);
492	    }
493	
494	    /**
495	     * Normalizes an optional owner email address. A {@code null} value means the field was omitted and
496	     * is left unset. When a value is present it must be a syntactically valid address whose domain is
497	     * not on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS}); the stored and
498	     * returned value is that address lower-cased.
499	     *
500	     * @param email the raw email value submitted by the client, or {@code null} if omitted
501	     * @return the lower-cased email, or {@code null} if none was supplied
502	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
503	     *                                     or its domain is a disposable-mail domain, yielding a 400
504	     *                                     response
505	     */
506	    private String normalizeEmail(String email) {
507	        if (email == null) {
508	            return null;
509	        }
510	        if (!EMAIL_PATTERN.matcher(email).matches()) {
511	            throw new InvalidOwnerFieldsException(List.of("email"));
512	        }
513	        String normalized = email.toLowerCase(Locale.ROOT);
514	        String domain = normalized.substring(normalized.indexOf('@') + 1);
515	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
516	            throw new InvalidOwnerFieldsException(List.of("email"));
517	        }
518	        return normalized;
519	    }
520	
521	    /**
522	     * Counts the existing owners that, before this create, already share the given first name and
523	     * last name. Both names are compared case-insensitively with surrounding and internal whitespace
524	     * collapsed, consistent with the other owner-name comparisons. The owner being created has not
525	     * been saved yet, so it is never included in the count.
526	     *
527	     * @param firstName the first name of the owner being created
528	     * @param lastName  the last name of the owner being created
529	     * @return the number of existing owners sharing both names
530	     */
531	    private int countNamesakes(String firstName, String lastName) {
532	        String normalizedFirstName = normalizeForComparison(firstName);
533	        String normalizedLastName = normalizeForComparison(lastName);
534	        return (int) this.clinicService.findAllOwners().stream()
535	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
536	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
537	            .count();
538	    }
539	
540	    /**
541	     * Builds the owner's {@code customerCode}, formatted {@code '<REGION>-<HASH8>'}. {@code REGION} is
542	     * the region code derived from the owner's postcode ({@link #regionForPostcode}, {@code 'UNKNOWN'}
543	     * when the postcode is absent or in no known range), and {@code HASH8} is the first eight
544	     * upper-cased hex characters of the SHA-256 digest of the owner's normalized telephone followed by
545	     * the last name (e.g. {@code 'NSW-1A2B3C4D'}). The identity carries no sequence number, so the
546	     * same postcode region, telephone and last name always yield the same customer code.
547	     *
548	     * @param postcode  the owner's validated postcode, or {@code null} if none was supplied
549	     * @param telephone the owner's normalized (E.164) telephone
550	     * @param lastName  the owner's last name
551	     * @return the formatted customer code
552	     */
553	    private String generateCustomerCode(String postcode, String telephone, String lastName) {
554	        String region = regionForPostcode(postcode);
555	        String hash8 = hashHex(telephone + lastName, 8);
556	        return region + "-" + hash8;
557	    }
558	
559	    /**
560	     * Resolves the region code for a postcode by its known 4-digit range in {@link #REGION_POSTCODES}
561	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), returning {@code 'UNKNOWN'}
562	     * when the postcode is {@code null}, not exactly 4 digits, or falls in no known range. This is the
563	     * {@code <REGION>} segment baked into the {@code customerCode}.
564	     *
565	     * @param postcode the owner's postcode, or {@code null}
566	     * @return the region code, or {@code 'UNKNOWN'}
567	     */
568	    private String regionForPostcode(String postcode) {
569	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
570	            return "UNKNOWN";
571	        }
572	        int value = Integer.parseInt(postcode);
573	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
574	            int[] range = entry.getValue();
575	            if (value >= range[0] && value <= range[1]) {
576	                return entry.getKey();
577	            }
578	        }
579	        return "UNKNOWN";
580	    }
581	
582	    /**
583	     * Resolves the region code for a city via the fixed {@link #CITY_REGION} table
584	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), returning {@code 'UNKNOWN'}
585	     * when the city is not listed. Used to validate an owner's optional postcode against its city's
586	     * region.
587	     *
588	     * @param city the owner's city
589	     * @return the region code, or {@code 'UNKNOWN'}
590	     */
591	    private String regionForCity(String city) {
592	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
593	    }
594	
595	    /**
596	     * Returns the first {@code length} upper-cased hex characters of the SHA-256 digest of the given
597	     * input. Used for the {@code <HASH8>} segment of a {@code customerCode} (length 8) and for the
598	     * deterministic {@code householdId} (length 12).
599	     *
600	     * @param input  the value to hash
601	     * @param length the number of leading hex characters to return
602	     * @return the first {@code length} upper-cased hex characters of its SHA-256 digest
603	     */
604	    private String hashHex(String input, int length) {
605	        try {
606	            byte[] digest = MessageDigest.getInstance("SHA-256")
607	                .digest(input.getBytes(StandardCharsets.UTF_8));
608	            StringBuilder hex = new StringBuilder(digest.length * 2);
609	            for (byte b : digest) {
610	                hex.append(String.format("%02x", b));
611	            }
612	            return hex.substring(0, length).toUpperCase(Locale.ROOT);
613	        } catch (NoSuchAlgorithmException e) {
614	            throw new IllegalStateException("SHA-256 algorithm not available", e);
615	        }
616	    }
617	
618	    /**
619	     * Counts the existing owners already in the given city, used to derive the per-city sequence of a
620	     * {@code customerCode}. Cities are compared case-insensitively with surrounding and internal
621	     * whitespace collapsed, consistent with the other owner-field comparisons. The owner being created
622	     * has not been saved yet, so it is never included in the count.
623	     *
624	     * @param city the city of the owner being created
625	     * @return the number of existing owners in that city
626	     */
627	    private int countOwnersInCity(String city) {
628	        String normalizedCity = normalizeForComparison(city);
629	        return (int) this.clinicService.findAllOwners().stream()
630	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
631	            .count();
632	    }
633	
634	    /**
635	     * Rejects creation of an owner whose city already contains the maximum number of owners
636	     * ({@value #CITY_CAPACITY}). Owners are counted per city case-insensitively with surrounding and
637	     * internal whitespace collapsed, consistent with the other owner-field comparisons.
638	     *
639	     * @param city the city of the owner being created
640	     * @throws OwnerCityAtCapacityException if the city already contains {@value #CITY_CAPACITY} or more
641	     *                                      owners, yielding a 409 Conflict response
642	     */
643	    private void rejectCityAtCapacity(String city) {
644	        if (countOwnersInCity(city) >= CITY_CAPACITY) {
645	            throw new OwnerCityAtCapacityException(city);
646	        }
647	    }
648	
649	    /**
650	     * Rejects creation of an owner once the given business day has already reached its daily quota
651	     * of {@value #DAILY_OWNER_LIMIT} owners. Owners are counted by their {@code registrationDate}
652	     * being that day — the adjusted business day the owner being created will carry — so the quota
653	     * applies per business day. The owner being created has not been saved yet, so it is never
654	     * included in the count.
655	     *
656	     * @param registrationDate the adjusted business-day registration date of the owner being created
657	     * @throws DailyOwnerLimitReachedException if {@value #DAILY_OWNER_LIMIT} or more owners already
658	     *                                         carry that registration date, yielding a
659	     *                                         429 Too Many Requests response
660	     */
661	    private void rejectDailyLimitReached(LocalDate registrationDate) {
662	        if (countOwnersRegisteredOn(registrationDate) >= DAILY_OWNER_LIMIT) {
663	            throw new DailyOwnerLimitReachedException(registrationDate);
664	        }
665	    }
666	
667	    /**
668	     * Counts the existing owners that carry the given day as their {@code registrationDate} — the same
669	     * per-business-day bucket the daily create-limit and the bulk-signup warning both accumulate over.
670	     *
671	     * @param registrationDate the business day to count owners for
672	     * @return the number of existing owners registered on that day
673	     */
674	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
675	        return this.clinicService.findAllOwners().stream()
676	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
677	            .count();
678	    }
679	
680	    /**
681	     * Sets the {@code bulkSignupWarning} flag on an owner response. The flag is {@code true} when more
682	     * than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the current business day's
683	     * {@code registrationDate} — the business day a create would land on right now — and {@code false}
684	     * otherwise.
685	     *
686	     * @param ownerDto the owner response to flag
687	     */
688	    private void applyBulkSignupWarning(OwnerDto ownerDto) {
689	        LocalDate today = toBusinessDay(LocalDate.now());
690	        ownerDto.setBulkSignupWarning(countOwnersRegisteredOn(today) > BULK_SIGNUP_WARNING_THRESHOLD);
691	    }
692	
693	    /**
694	     * Rolls a registration date forward to a business day. A date that falls on a Saturday or Sunday
695	     * is rolled forward to the next Monday; a date already on a weekday is returned unchanged. This
696	     * applies to the effective registration date whether it was supplied in the request or defaulted
697	     * to the server date, and the adjusted value is what gets stored as {@code registrationDate} and
698	     * feeds every value derived from it (such as the membership number's year segment and the daily
699	     * create-limit's per-day bucket).
700	     *
701	     * @param date the effective registration date, supplied or defaulted
702	     * @return the same date when it is a weekday, otherwise the next Monday
703	     */
704	    private LocalDate toBusinessDay(LocalDate date) {
705	        LocalDate adjusted = date;
706	        while (adjusted.getDayOfWeek() == DayOfWeek.SATURDAY
707	            || adjusted.getDayOfWeek() == DayOfWeek.SUNDAY) {
708	            adjusted = adjusted.plusDays(1);
709	        }
710	        return adjusted;
711	    }
712	
713	    /**
714	     * Rejects creation of an owner whose derived {@code identityKey} exactly matches an existing
715	     * owner's. The identity key — {@code '<normalizedTelephone>|<email or empty>|<householdId or
716	     * empty>'} — is the single value that consolidates all duplicate detection: the previously
717	     * separate telephone, email and household checks are all expressed through it. Because the
718	     * telephone is part of the key, two members of the same household (same {@code householdId})
719	     * with different telephones have different identity keys and are both allowed; only a whole-key
720	     * match is a duplicate. The owner being created already carries its normalized telephone,
721	     * email and (if any) household id, and existing owners store the same normalized forms, so the
722	     * keys are compared directly.
723	     *
724	     * @param owner the owner being created, with its telephone, email and household id already set
725	     * @throws DuplicateOwnerIdentityException if another owner already has the same identity key,
726	     *                                         yielding a 409 Conflict response
727	     */
728	    private void rejectDuplicateIdentity(Owner owner) {
729	        String identityKey = owner.getIdentityKey();
730	        boolean inUse = this.clinicService.findAllOwners().stream()
731	            .map(Owner::getIdentityKey)
732	            .anyMatch(identityKey::equals);
733	        if (inUse) {
734	            throw new DuplicateOwnerIdentityException(identityKey);
735	        }
736	    }
737	
738	    /**
739	     * Flags the owner being created as a possible (soft) duplicate. A possible duplicate is an owner
740	     * that is not a hard duplicate (its identity key is unique, so it has already passed
741	     * {@link #rejectDuplicateIdentity}) yet belongs to the same household as an existing owner — that
742	     * is, it carries the same computed {@code householdId} (derived from the last name and postcode) —
743	     * while carrying a different telephone. When such a match exists the owner is created with
744	     * {@code possibleDuplicate} set to {@code true} and {@code possibleDuplicateOf} set to the matching
745	     * owner's id (the earliest matching owner by id); otherwise {@code possibleDuplicate} is
746	     * {@code false} and {@code possibleDuplicateOf} is left unset.
747	     *
748	     * <p>An owner that declares household membership via {@code sharesHousehold} is never flagged: a
749	     * declared household member is not a suspected duplicate. (Without that declaration a same-household
750	     * owner is rejected outright by {@link #rejectHouseholdDuplicate}, so no suspected-duplicate match
751	     * survives for a created owner either.)
752	     *
753	     * @param owner           the owner being created, with its household id and telephone already set
754	     * @param sharesHousehold whether the owner declared itself a member of an existing household
755	     */
756	    private void applyPossibleDuplicate(Owner owner, boolean sharesHousehold) {
757	        owner.setPossibleDuplicate(false);
758	        if (sharesHousehold) {
759	            return;
760	        }
761	        String householdId = owner.getHouseholdId();
762	        if (householdId == null || householdId.isBlank()) {
763	            return;
764	        }
765	        String telephone = owner.getTelephone();
766	        Owner match = this.clinicService.findAllOwners().stream()
767	            .filter(existing -> householdId.equals(existing.getHouseholdId())
768	                && !Objects.equals(telephone, existing.getTelephone()))
769	            .min(Comparator.comparingInt(Owner::getId))
770	            .orElse(null);
771	        if (match != null) {
772	            owner.setPossibleDuplicate(true);
773	            owner.setPossibleDuplicateOf(match.getId());
774	        }
775	    }
776	
777	    /**
778	     * Computes the owner's deterministic {@code householdId}: the first twelve upper-cased hex
779	     * characters of the SHA-256 digest of the normalized last name and the postcode joined by a
780	     * {@code '|'}. Because the value derives only from the last name and postcode, every owner that
781	     * shares both automatically shares the same household id, so the household is keyed on
782	     * {@code (lastName, postcode)} with no opt-in required. The last name is normalized for comparison
783	     * (trimmed, internal whitespace collapsed, lower-cased) so values differing only in case or spacing
784	     * still land in the same household.
785	     *
786	     * @param lastName the owner's last name
787	     * @param postcode the owner's validated postcode, or {@code null} if none was supplied
788	     * @return the derived household id, or {@code null} when the owner has no postcode and so belongs
789	     *         to no postcode-keyed household
790	     */
791	    private String computeHouseholdId(String lastName, String postcode) {
792	        if (postcode == null) {
793	            return null;
794	        }
795	        return hashHex(normalizeForComparison(lastName) + "|" + postcode, 12);
796	    }
797	
798	    /**
799	     * Rejects creation of an owner that would join an existing household it has not declared membership
800	     * of. The household is keyed on the computed {@code householdId} (derived from the last name and
801	     * postcode), so any existing owner carrying the same {@code householdId} is a member of the same
802	     * household. A second owner in that household is a household duplicate and is rejected with a
803	     * {@code 409 Conflict} unless the request opts in via {@code sharesHousehold}, in which case this
804	     * check is bypassed and the owner is created as a declared household member. An owner with no
805	     * {@code householdId} (no postcode) belongs to no household and is never rejected here.
806	     *
807	     * @param owner the owner being created, with its household id already computed
808	     * @throws DuplicateHouseholdException if an existing owner already belongs to the same
809	     *                                     household, yielding a 409 Conflict response
810	     */
811	    private void rejectHouseholdDuplicate(Owner owner) {
812	        String householdId = owner.getHouseholdId();
813	        if (householdId == null || householdId.isBlank()) {
814	            return;
815	        }
816	        boolean inUse = this.clinicService.findAllOwners().stream()
817	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
818	        if (inUse) {
819	            throw new DuplicateHouseholdException(householdId);
820	        }
821	    }
822	
823	    /**
824	     * Normalizes a text value for case- and whitespace-insensitive comparison: surrounding
825	     * whitespace is trimmed, every internal run of whitespace is collapsed to a single space, and
826	     * the result is lower-cased.
827	     *
828	     * @param value the value to normalize, possibly {@code null}
829	     * @return the normalized value, or an empty string if {@code value} is {@code null}
830	     */
831	    private String normalizeForComparison(String value) {
832	        if (value == null) {
833	            return "";
834	        }
835	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
836	    }
837	
838	    /**
839	     * Normalizes an owner address for storage, display and comparison. Surrounding whitespace is
840	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
841	     * upper-cased, and common street-type abbreviations appearing as whole tokens are expanded
842	     * ({@code ST} to {@code STREET}, {@code RD} to {@code ROAD}, {@code AVE} to {@code AVENUE}).
843	     * This normalized value is what gets stored and returned.
844	     *
845	     * @param address the raw address value submitted by the client, possibly {@code null}
846	     * @return the normalized address, or an empty string if {@code address} is {@code null}
847	     */
848	    private String normalizeAddress(String address) {
849	        if (address == null) {
850	            return "";
851	        }
852	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
853	        if (collapsed.isEmpty()) {
854	            return collapsed;
855	        }
856	        String[] tokens = collapsed.split(" ");
857	        StringBuilder normalized = new StringBuilder(collapsed.length());
858	        for (int i = 0; i < tokens.length; i++) {
859	            if (i > 0) {
860	                normalized.append(' ');
861	            }
862	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
863	        }
864	        return normalized.toString();
865	    }
866	}
